const helpSec = await graphql_help({ for: 'security' });
const helpRuntime = await graphql_help({ for: 'runtime' });
const helpWatches = await query_catalog({ id: 'help:watches' });
const res = await execute_graphql({
  query: `mutation {
    gj_watch(insert: {
      name: "deeporg_failed_invoices",
      query: "subscription watch_failed_invoices { invoices(where: { status: { eq: \"failed\" } }) { id status amount_cents } }",
      delivery_json: {
        kind: "inbox",
        digest: {
          window: "1h"
        }
      }
    }) {
      id
      name
      status
      enabled
      delivery_json
    }
  }`
});
await final('Created durable watch named deeporg_failed_invoices to monitor failed invoice changes and deliver an inbox digest hourly.', { res, helpSec, helpRuntime, helpWatches });

